('q_lit-1-lidove-pohadky_0','V které pohádce nese dívka babičce koláče?',ARRAY['Zlatovláska','Červená Karkulka','Sněhurka','Popelka']::TEXT[],1,'Červená Karkulka.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_1','Kdo se v pohádce převlékl za babičku?',ARRAY['medvěd','vlk','zajíc','liška']::TEXT[],1,'Vlk.',1,ARRAY[]::TEXT[],NULL,1,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_2','Kdo bydlí v perníkové chaloupce?',ARRAY['zlá čarodějnice','dobrý král','princ','drak']::TEXT[],0,'Jeník a Mařenka.',1,ARRAY[]::TEXT[],NULL,2,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_3','Kolik trpaslíků bydlelo se Sněhurkou?',ARRAY['deset','pět','tři','sedm']::TEXT[],3,'Sedm.',2,ARRAY[]::TEXT[],NULL,3,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_4','V které pohádce vaří hrneček kaši?',ARRAY['Červená Karkulka','O veliké řepě','Sněhurka','Hrnečku, vař!']::TEXT[],3,'Hrnečku, vař!',2,ARRAY[]::TEXT[],NULL,4,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_5','Jak se jmenuje pohádka o zvířátkách, které chtějí vytáhnout řepu?',ARRAY['O perníkové chaloupce','O pyšné princezně','O Smolíčkovi','O veliké řepě']::TEXT[],3,'Řepa.',2,ARRAY[]::TEXT[],NULL,5,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_6','Co ztratila Popelka na schodech?',ARRAY['prsten','klobouk','rukavici','střevíc']::TEXT[],3,'Střevíček.',3,ARRAY[]::TEXT[],NULL,6,'c_lit-1-lidove-pohadky',NULL,NOW()),
('q_lit-1-lidove-pohadky_7','Který pohádkový tvor je v rybníce?',ARRAY['čert','drak','trpaslík','vodník']::TEXT[],3,'Vodník.',3,ARRAY[]::TEXT[],NULL,7,'c_lit-1-lidove-pohadky',NULL,NOW()),
